//! M8D1: canonical hash-consed Shannon proof DAG with certified local counts.
//!
//! A source-bound S8C1 structural Boolean DAG is checked independently.
//! Eight root bucket counts use nodes shared across identical proof subtrees.
//! Each DAG reference is checked under EVERY (bucket, depth, prefix) context,
//! including references reached by multiple different primary assignments.
//! This prevents soundness from relying on an unsound context-free memo.
//!
//! Emitter currently compresses a complete D8C1 tree generated by an
//! exhaustive producer. The *checker* is non-enumerative, but this does NOT
//! establish non-exhaustive proof generation or scalable WMC performance.
use super::{sha256,Check,Error,Cursor,two_copy_structural,two_copy_count_trace};
use super::two_copy_structural::{Structural,Op};
use std::collections::{BTreeMap,BTreeSet};

const MAGIC:&[u8;4]=b"M8D1";
const D8C1_HEADER:usize=4+32*3+1;
const HEADER:usize=4+32*3+1+2;
const MAX_NODES:usize=8192;
const MAX_BYTES:usize=65_536;
const INVALID:u16=u16::MAX;
#[derive(Clone,Copy,Debug,PartialEq,Eq,PartialOrd,Ord)]
struct Node {
    tag:u8, depth:u8, count:u16, left:u16, right:u16,
}
#[derive(Clone,Debug,PartialEq,Eq)]
pub(super) struct DagCounts {
    pub(super) buckets:[u16;8],
    pub(super) nodes:usize,
    pub(super) contexts:usize,
    pub(super) shared_contexts:usize,
}
fn ingest(
    reader:&mut Cursor<'_>,depth:usize,primary:usize,
    nodes:&mut Vec<Node>,index:&mut BTreeMap<Node,u16>,
)->Check<u16>{
    if depth>primary{return Err(Error::InvalidProof);}
    let tag=reader.u8()?;
    let count=u16::try_from(reader.u16()?).map_err(|_|Error::InvalidProof)?;
    let (left,right)=match tag {
        0|1=>(INVALID,INVALID),
        2=>{
            if depth==primary{return Err(Error::InvalidProof);}
            let left=ingest(reader,depth+1,primary,nodes,index)?;
            let right=ingest(reader,depth+1,primary,nodes,index)?;
            (left,right)
        }
        _=>return Err(Error::InvalidProof),
    };
    let node=Node{
        tag,depth:depth as u8,count,left,right
    };
    if let Some(&existing)=index.get(&node){return Ok(existing);}
    if nodes.len()>=MAX_NODES{return Err(Error::UnknownResource);}
    let id=u16::try_from(nodes.len()).map_err(|_|Error::UnknownResource)?;
    nodes.push(node);
    index.insert(node,id);
    Ok(id)
}
pub(super) fn emit(src:&[u8],proof:&[u8],structure:&[u8])->Check<Vec<u8>>{
    let circuit=two_copy_structural::verify_schema_without_enumeration(
        src,proof,structure
    )?;
    if circuit.primary>8{return Err(Error::UnknownResource);}
    // The generator is deliberately not advertised as non-exhaustive:
    // it starts from the existing, exhaustively produced D8C1 proof.
    let tree=two_copy_count_trace::emit(src,proof,structure)?;
    if tree.len()<D8C1_HEADER || &tree[..4]!=b"D8C1" {
        return Err(Error::InvalidProof);
    }
    let mut reader=Cursor::new(&tree[D8C1_HEADER..]);
    let mut nodes=Vec::new();
    let mut intern=BTreeMap::new();
    let mut roots=[0u16;8];
    for root in &mut roots {
        *root=ingest(&mut reader,0,circuit.primary,&mut nodes,&mut intern)?;
    }
    if reader.at!=tree.len()-D8C1_HEADER{return Err(Error::InvalidProof);}
    let mut data=Vec::with_capacity(HEADER+8*nodes.len()+16);
    data.extend_from_slice(MAGIC);
    data.extend_from_slice(&sha256(src));
    data.extend_from_slice(&sha256(proof));
    data.extend_from_slice(&sha256(structure));
    data.push(circuit.primary as u8);
    data.extend_from_slice(&(nodes.len() as u16).to_le_bytes());
    for node in nodes {
        data.push(node.tag);
        data.push(node.depth);
        data.extend_from_slice(&node.count.to_le_bytes());
        data.extend_from_slice(&node.left.to_le_bytes());
        data.extend_from_slice(&node.right.to_le_bytes());
    }
    for id in roots {data.extend_from_slice(&id.to_le_bytes());}
    if data.len()>MAX_BYTES{return Err(Error::UnknownResource);}
    Ok(data)
}
// Separate, conservative Kleene evaluator. It deliberately does NOT
// reuse D8C1's partial_bucket or trust its emitter's leaf decisions.
fn partial(
    c:&Structural,bucket:usize,depth:usize,prefix:usize
)->Check<Option<bool>>{
    if c.primary>8 || bucket>=8 || depth>c.primary
        || prefix>>depth!=0 {return Err(Error::InvalidProof);}
    let mut values=Vec::with_capacity(c.primary+c.gates.len());
    for bit in 0..c.primary {
        values.push(if bit>=depth {None}
            else {Some(prefix&(1usize<<bit)!=0)});
    }
    for gate in &c.gates {
        let limit=values.len();
        let get=|id:u16|->Check<Option<bool>>{
            if id as usize>=limit{return Err(Error::InvalidProof);}
            Ok(values[id as usize])
        };
        let v=match gate.op{
            Op::Zero=>Some(false),
            Op::One=>Some(true),
            Op::Not=>get(gate.a)?.map(|x|!x),
            Op::And=>{
                let (a,b)=(get(gate.a)?,get(gate.b)?);
                if a==Some(false)||b==Some(false){Some(false)}
                else if a==Some(true)&&b==Some(true){Some(true)}
                else {None}
            }
            Op::Or=>{
                let (a,b)=(get(gate.a)?,get(gate.b)?);
                if a==Some(true)||b==Some(true){Some(true)}
                else if a==Some(false)&&b==Some(false){Some(false)}
                else {None}
            }
            Op::Xor=>{
                match (get(gate.a)?,get(gate.b)?) {
                    (Some(a),Some(b))=>Some(a^b),
                    _=>None
                }
            }
        };
        values.push(v);
    }
    values.get(c.bucket[bucket] as usize).copied()
        .ok_or(Error::InvalidProof)
}
fn verify_context(
    c:&Structural,nodes:&[Node],id:u16,bucket:usize,
    depth:usize,prefix:usize,
    used:&mut [bool],seen:&mut BTreeSet<(u16,usize,usize)>,
)->Check<u16>{
    let node=*nodes.get(id as usize).ok_or(Error::InvalidProof)?;
    if node.depth as usize!=depth{return Err(Error::InvalidProof);}
    used[id as usize]=true;
    if !seen.insert((id,bucket,prefix)){return Ok(node.count);}
    if seen.len()>MAX_NODES{return Err(Error::UnknownResource);}
    match partial(c,bucket,depth,prefix)? {
        Some(false)=>{
            if node.tag!=0 || node.count!=0{return Err(Error::InvalidProof);}
        }
        Some(true)=>{
            let expected=1usize<<c.primary.saturating_sub(depth);
            if node.tag!=1 || node.count as usize!=expected {
                return Err(Error::InvalidProof);
            }
        }
        None=>{
            if node.tag!=2 || depth>=c.primary{
                return Err(Error::InvalidProof);
            }
            let left=verify_context(c,nodes,node.left,bucket,
                depth+1,prefix,used,seen)?;
            let right=verify_context(c,nodes,node.right,bucket,
                depth+1,prefix|(1usize<<depth),used,seen)?;
            if left.checked_add(right)!=Some(node.count){
                return Err(Error::InvalidProof);
            }
        }
    }
    Ok(node.count)
}
pub(super) fn verify(
    src:&[u8],proof:&[u8],structure:&[u8],bytes:&[u8],
)->Check<DagCounts>{
    if bytes.len()>MAX_BYTES{return Err(Error::UnknownResource);}
    if bytes.len()<HEADER+16{return Err(Error::InvalidProof);}
    let circuit=two_copy_structural::verify_schema_without_enumeration(
        src,proof,structure
    )?;
    if circuit.primary>8{return Err(Error::UnknownResource);}
    let mut reader=Cursor::new(bytes);
    if reader.bytes(4)?!=MAGIC
        ||reader.bytes(32)?!=sha256(src)
        ||reader.bytes(32)?!=sha256(proof)
        ||reader.bytes(32)?!=sha256(structure)
        ||reader.u8()? as usize!=circuit.primary {
        return Err(Error::InvalidProof);
    }
    let n=reader.u16()?;
    if n==0 || n>MAX_NODES{return Err(Error::UnknownResource);}
    let expected=HEADER.checked_add(n.checked_mul(8)
        .ok_or(Error::UnknownResource)?)
        .and_then(|p|p.checked_add(16))
        .ok_or(Error::UnknownResource)?;
    if expected!=bytes.len(){return Err(Error::InvalidProof);}
    let mut nodes=Vec::with_capacity(n);
    let mut distinct=BTreeSet::new();
    for index in 0..n{
        let tag=reader.u8()?;
        let depth=reader.u8()?;
        let count=u16::try_from(reader.u16()?).map_err(|_|Error::InvalidProof)?;
        let left=u16::try_from(reader.u16()?).map_err(|_|Error::InvalidProof)?;
        let right=u16::try_from(reader.u16()?).map_err(|_|Error::InvalidProof)?;
        let node=Node{tag,depth,count,left,right};
        if depth as usize>circuit.primary ||
            count as usize>(1usize<<(circuit.primary-depth as usize)){
            return Err(Error::InvalidProof);
        }
        match tag {
            0 if count==0 && left==INVALID && right==INVALID=>{},
            1 if count as usize==1usize<<(circuit.primary-depth as usize)
                && left==INVALID && right==INVALID=>{},
            2 if (depth as usize)<circuit.primary
                && (left as usize)<index && (right as usize)<index=>{
                let l=nodes[left as usize].count;
                let r=nodes[right as usize].count;
                if nodes[left as usize].depth!=depth+1
                    || nodes[right as usize].depth!=depth+1
                    || l.checked_add(r)!=Some(count){
                    return Err(Error::InvalidProof);
                }
            }
            _=>return Err(Error::InvalidProof),
        }
        if !distinct.insert(node){return Err(Error::InvalidProof);}
        nodes.push(node);
    }
    let mut roots=[0u16;8];
    for id in &mut roots {
        *id=u16::try_from(reader.u16()?).map_err(|_|Error::InvalidProof)?;
        if *id as usize>=n || nodes[*id as usize].depth!=0{
            return Err(Error::InvalidProof);
        }
    }
    if reader.at!=bytes.len(){return Err(Error::InvalidProof);}
    let mut used=vec![false;n];
    let mut seen=BTreeSet::new();
    let mut buckets=[0u16;8];
    for (bucket,root) in roots.iter().enumerate() {
        buckets[bucket]=verify_context(&circuit,&nodes,*root,bucket,
            0,0,&mut used,&mut seen)?;
    }
    if used.iter().any(|&v|!v){return Err(Error::InvalidProof);}
    let contexts=seen.len();
    Ok(DagCounts{
        buckets,nodes:n,contexts,
        shared_contexts:contexts.checked_sub(n).ok_or(Error::InvalidProof)?,
    })
}
#[cfg(test)]
mod tests {
    use super::*;
    use super::two_copy_structural::Gate;
    #[test]
    fn independent_partial_boolean_evaluator_is_conservative(){
        let c=Structural{
            primary:1,gates:vec![
                Gate{op:Op::Zero,a:0,b:0},
                Gate{op:Op::Xor,a:0,b:0}
            ],bucket:[2;8]
        };
        assert_eq!(partial(&c,0,0,0),Ok(None));
        assert_eq!(partial(&c,0,1,0),Ok(Some(false)));
        assert_eq!(partial(&c,0,1,1),Ok(Some(false)));
    }
    #[test]
    fn shared_false_cube_must_be_checked_at_all_bucket_roots(){
        let c=Structural{
            primary:1,gates:vec![Gate{op:Op::Zero,a:0,b:0}],
            bucket:[1;8]
        };
        let node=Node{tag:0,depth:0,count:0,left:INVALID,right:INVALID};
        let mut used=vec![false];
        let mut seen=BTreeSet::new();
        for bucket in 0..8 {
            assert_eq!(
                verify_context(&c,&[node],0,bucket,0,0,&mut used,&mut seen),
                Ok(0)
            );
        }
        assert_eq!(seen.len(),8);
        assert!(used[0]);
        let mut wrong=c;
        wrong.bucket[1]=0; // bucket 1 is now the unconstrained primary bit
        assert_eq!(
            verify_context(&wrong,&[node],0,1,0,0,
                &mut vec![false],&mut BTreeSet::new()),
            Err(Error::InvalidProof)
        );
    }
}
